<script setup lang="ts">
import { computed,ref,watch } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { Download,Plus,RefreshCw,Search } from 'lucide-vue-next';
import { ElMessage } from 'element-plus';
import { useSessionStore } from '../stores/session';
import { fail,overdue,permission,sf,sl,statusTone } from '../safety-workspace';
import { exportAdmission } from '../admission';
import { useSafetyList } from '../useSafetyList';
import QueryPanel from '../components/QueryPanel.vue';
import QueryField from '../components/QueryField.vue';
import SafetyTaskDrawer from '../components/SafetyTaskDrawer.vue';
import SafetyTaskEditor from '../components/SafetyTaskEditor.vue';
import '../subject-management.css';import '../safety-workspace.css';
const route=useRoute(),router=useRouter(),session=useSessionStore(),enterprise=computed(()=>session.user?.portal==='ENTERPRISE');
const {filters,rows,total,page,loading,error,search,reset,load,getFilters}=useSafetyList('/safety/workspace/tasks',{q:'',status:'',taskType:'',queue:''});
const table=ref<any>();const selected=ref<any[]>([]),drawer=ref(false),taskId=ref(''),taskType=ref(''),editor=ref(false),exporting=ref(false),taskDrawer=ref<InstanceType<typeof SafetyTaskDrawer>>();
async function open(row:any){if(drawer.value&&!await taskDrawer.value?.confirmDiscard())return;taskId.value=row.id;taskType.value=row.taskType;drawer.value=true;void router.replace({path:route.path,query:{...route.query,taskId:row.id,taskTypeSelected:row.taskType}})}
async function created(row:any){await load();await open(row)}
async function exportRows(){exporting.value=true;try{await exportAdmission('/safety/workspace/tasks',getFilters(),[['任务名称',r=>r.title],['任务编号',r=>r.businessNo],['任务类型',r=>sl(r.taskType)],['责任企业',r=>r.enterprise?.name],['状态',r=>sl(r.status)],['办理期限',r=>sf(r.dueAt)]],'安全监管任务',selected.value)}catch(e){ElMessage.error(fail(e))}finally{exporting.value=false}}
function bucket(value:string){filters.status=value;filters.queue='';search()}
watch(()=>route.query,q=>{if(q.taskId&&q.taskTypeSelected&&taskId.value!==q.taskId){taskId.value=String(q.taskId);taskType.value=String(q.taskTypeSelected);drawer.value=true}},{immediate:true});
watch(drawer,v=>{if(!v&&route.query.taskId)void router.replace({path:route.path,query:{...route.query,taskId:undefined,taskTypeSelected:undefined}})});watch(rows,()=>{selected.value=[];table.value?.clearSelection()});
</script>
<template><section class="city-subject-page safety-workspace-page" :class="{'safety-drawer-open':drawer}"><h1 class="sr-only">应急整改</h1><QueryPanel class="subject-query" :loading="loading" @search="search()" @reset="reset"><QueryField label="关键词" keyword><el-input v-model="filters.q" aria-label="搜索安全监管任务" :prefix-icon="Search" clearable placeholder="搜索任务编号、名称或企业"/></QueryField><QueryField label="任务类型"><el-select v-model="filters.taskType" aria-label="任务类型" clearable placeholder="全部类型"><el-option label="应急处置" value="EMERGENCY"/><el-option label="整改任务" value="RECTIFICATION"/></el-select></QueryField><QueryField label="办理状态"><el-select v-model="filters.status" aria-label="办理状态" clearable placeholder="全部状态"><el-option v-for="status in ['PENDING_DISPATCH','WAITING_RESPONSE','IN_PROGRESS','PENDING_REVIEW','CLOSED']" :key="status" :label="sl(status)" :value="status"/></el-select></QueryField></QueryPanel><section class="safety-surface"><header class="safety-header"><h2>{{enterprise?'应急响应与整改':'应急整改'}}<span class="subject-count">{{total}}</span></h2><div><el-button :icon="RefreshCw" :loading="loading" @click="load">刷新</el-button><el-button :icon="Download" :loading="exporting" @click="exportRows">导出</el-button><el-button v-if="!enterprise&&permission(session.user,'safety:emergency:dispatch')" :icon="Plus" type="primary" @click="editor=true">新建任务</el-button></div></header><div class="safety-tabs" style="margin-bottom:12px"><button v-for="status in ['', 'WAITING_RESPONSE','IN_PROGRESS','PENDING_REVIEW','CLOSED']" :key="status" type="button" :aria-pressed="filters.status===status&&!filters.queue" @click="bucket(status)">{{status?sl(status):'全部任务'}}</button><button type="button" :aria-pressed="filters.queue==='OVERDUE'" @click="filters.queue='OVERDUE';filters.status='';search()">已超期</button></div><div v-if="selected.length" class="subject-bulk"><span>已选 {{selected.length}} 项</span><el-button link type="primary" :loading="exporting" @click="exportRows">导出所选</el-button><el-button link @click="table?.clearSelection()">取消选择</el-button></div><div v-if="error" class="safety-error"><strong>任务列表暂时无法读取</strong><span>{{error}}</span><el-button @click="load">重试</el-button></div><div v-else class="safety-table-host"><el-table ref="table" v-loading="loading" :data="rows" height="100%" class="subject-table" :row-key="(r:any)=>`${r.taskType}:${r.id}`" empty-text="暂无符合条件的任务" :row-class-name="({row}:any)=>row.id===taskId&&drawer?'safety-row-selected':''" @selection-change="selected=$event"><el-table-column type="selection" width="44"/><el-table-column label="任务名称 / 编号" min-width="255"><template #default="{row}"><button class="subject-identity" type="button" @click="open(row)"><strong>{{row.title}}</strong><span>{{row.businessNo}}</span></button></template></el-table-column><el-table-column label="类型" width="104"><template #default="{row}"><el-tag size="small" :type="row.taskType==='RECTIFICATION'?'warning':'primary'">{{sl(row.taskType)}}</el-tag></template></el-table-column><el-table-column v-if="!enterprise" label="责任企业" min-width="195"><template #default="{row}">{{row.enterprise?.name}}</template></el-table-column><el-table-column label="办理状态 / 截止时间" width="165"><template #default="{row}"><el-tag size="small" :type="statusTone(row.status)">{{row.taskType==='RECTIFICATION'&&row.status==='IN_PROGRESS'?'整改中':sl(row.status)}}</el-tag><el-tag v-if="overdue(row)" size="small" type="danger" style="margin-left:5px">超期</el-tag><time class="safety-deadline" :class="{overdue:overdue(row)}">{{sf(row.dueAt)}}</time></template></el-table-column><el-table-column label="操作" width="105" fixed="right"><template #default="{row}"><el-button link type="primary" @click="open(row)">{{row.status==='PENDING_REVIEW'&&!enterprise&&permission(session.user,'safety:emergency:review')?'复核':'详情'}}</el-button></template></el-table-column></el-table></div><footer class="subject-footer"><span>共 {{total}} 条</span><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev,pager,next" @current-change="search(false)"/></footer></section><SafetyTaskDrawer ref="taskDrawer" v-model="drawer" :id="taskId" :task-type="taskType" @changed="load"/><SafetyTaskEditor v-model="editor" @created="created"/></section></template>
